with sources as (
 select e.key sku,e.value d from quarter_input q,jsonb_each(q.payload->'items') e
), calculated as (
 select p.version_id,p.sku_code,p.avg_daily_qty,p.avg_daily_hl,(s.d->>'stock_avg_qty')::numeric+(s.d->>'pull_qty')::numeric ceiling_qty
 from stock_policy_items p join stock_policy_versions v on v.id=p.version_id join sources s on s.sku=p.sku_code
 where v.code='T1/2026' and v.status='draft' and v.oor_enabled=false
 and lower(trim(p.unit_code))=lower(s.d->>'unit')
 and p.avg_daily_qty>0 and p.avg_daily_hl>0
 and (s.d->>'stock_avg_qty')::numeric+(s.d->>'pull_qty')::numeric >= p.objective_qty
)
update stock_policy_items p set max_qty=c.ceiling_qty,over_qty=c.ceiling_qty,
 max_days=c.ceiling_qty/c.avg_daily_qty,max_hl=c.ceiling_qty*c.avg_daily_hl/c.avg_daily_qty,
 policy_source='TRIMESTRAL_020502_020501_PARCIAL',
 source_file=coalesce(p.source_file,'')||' | 020502 e 020501 out-dez/2025',
 suggestion_basis='Máximo = média do disponível 020502 + puxada acumulada 020501, ambos na unidade comercial do SKU. Dias máximos = máximo / média de vendas. Entradas 251 e 314; armazém e depósito 1. Dz convertido para caixas por /2; litros permanecem litros. Rascunho pendente de confirmação do período de vendas; sem aplicação ao OOR.',
 review_flags=(select coalesce(jsonb_agg(x),'[]') from jsonb_array_elements(p.review_flags) x where x #>> '{}' not in ('PUXADA_TRIMESTRAL_INCOMPLETA','ESTOQUE_2025_PENDENTE'))||case when c.ceiling_qty<p.objective_qty then '["MAXIMO_ABAIXO_OBJETIVO"]'::jsonb else '[]'::jsonb end,
 review_note='Bases de estoque e puxada de outubro–dezembro/2025 incorporadas. Confirmar período das vendas antes de concluir.'
from calculated c where p.version_id=c.version_id and p.sku_code=c.sku_code;
update stock_policy_versions v set calculation_metadata=v.calculation_metadata||jsonb_build_object(
 'stock_days',(select payload->'stock_days' from quarter_input),
 'pull_days',(select payload->'pull_days' from quarter_input),
 'review_source_2025',(select payload from quarter_input),
 'pending_maximum_items',(select count(*) from stock_policy_items p where p.version_id=v.id and p.max_qty is null),
 'missing',jsonb_build_array('Confirmação do período e dias trabalhados das vendas','Revisão dos SKUs sem base de vendas ou conversão compatível'),
 'readiness','partial'),updated_at=now()
where v.code='T1/2026' and v.status='draft' and v.oor_enabled=false;
